<script>
(()=>{const form=document.querySelector('.shop-filter-form'),sidebar=document.getElementById('shopFilters'),backdrop=document.getElementById('sheetBackdrop'),toast=document.getElementById('shopToast');let toastTimer;function notify(m){toast.textContent=m;toast.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.style.opacity='0',2600)}
document.querySelectorAll('[data-category-toggle]').forEach(b=>b.addEventListener('click',()=>{const g=b.closest('.cat-group');g.classList.toggle('open');b.setAttribute('aria-expanded',g.classList.contains('open')?'true':'false')}));
const accountWrap=document.getElementById('accountMenuWrap'),accountTrigger=document.getElementById('accountTrigger');accountTrigger?.addEventListener('click',()=>{const open=accountWrap.classList.toggle('open');accountTrigger.setAttribute('aria-expanded',open?'true':'false')});
const notificationWrap=document.getElementById('notificationWrap'),notificationTrigger=document.getElementById('notificationTrigger');notificationTrigger?.addEventListener('click',()=>{const open=notificationWrap.classList.toggle('open');notificationTrigger.setAttribute('aria-expanded',open?'true':'false')});
document.getElementById('filterOpen')?.addEventListener('click',()=>{sidebar.classList.add('sheet-open');backdrop.classList.add('open')});backdrop.addEventListener('click',()=>{sidebar.classList.remove('sheet-open');backdrop.classList.remove('open')});
document.querySelectorAll('.quick-prices button').forEach(b=>b.addEventListener('click',()=>{form.elements.min_price.value=b.dataset.min;form.elements.max_price.value=b.dataset.max}));
document.getElementById('sortSelect').addEventListener('change',e=>{const u=new URL(location.href);u.searchParams.set('sort',e.target.value);u.searchParams.delete('page');location.href=u});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{const u=new URL(location.href);u.searchParams.set('view',b.dataset.view);u.searchParams.delete('page');location.href=u}));
document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{const u=new URL(location.href);u.searchParams.delete(b.dataset.remove);u.searchParams.delete('page');location.href=u}));
document.querySelectorAll('.heart-button').forEach(b=>b.addEventListener('click',async()=>{if(b.dataset.auth!=='1'){notify('Sign in to save products.');setTimeout(()=>location.href=b.dataset.wishlistUrl,700);return}b.disabled=true;try{const r=await fetch(b.dataset.wishlistUrl,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}});const d=await r.json();if(!r.ok)throw new Error(d.message||'Could not update wishlist.');b.dataset.saved=d.saved?'1':'0';b.classList.toggle('saved',d.saved);b.setAttribute('aria-pressed',d.saved?'true':'false');b.setAttribute('aria-label',(d.saved?'Remove ':'Add ')+b.closest('.product-card').querySelector('.product-name').textContent+' '+(d.saved?'from':'to')+' wishlist');b.querySelector('svg').setAttribute('fill',d.saved?'currentColor':'none');notify(d.message)}catch(e){notify(e.message)}finally{b.disabled=false}}));
})();
</script>
